{{ config(materialized='table', tags=['inventory', 'domain:performance', 'tier:standard']) }}
-- GENERATED by tools/generate_models.py from app/queries/app/performance/perf_failure_causes_daily.sql (app-owned). Do not edit.
{%- set windows = var('windows', [7, 30, 90]) %}
{%- for w in windows %}
SELECT {{ w }} AS window_days, q.*
FROM (
{%- if target.type == 'duckdb' %}
WITH stmt_fail AS (
  SELECT 'warehouse' AS resource_type, workspace_id, compute.warehouse_id AS resource_id, CAST(start_time AS DATE) AS usage_date,
         COALESCE(NULLIF(regexp_extract(error_message, concat('^', chr(92), '[([A-Za-z0-9_.]+)', chr(92), ']'), 1), ''), 'unclassified') AS cause
  FROM {{ source('system_query', 'history') }}
  WHERE execution_status = 'FAILED'
    AND compute.warehouse_id IS NOT NULL
    AND start_time >= {{ audit_today() }} - (({{ w }}) * INTERVAL 1 DAY)
    AND start_time < {{ audit_today() }}
),
run_rows AS (
  SELECT workspace_id, job_id, run_id, period_end_time, result_state, termination_code,
         MIN(period_start_time) OVER (PARTITION BY workspace_id, job_id, run_id) AS run_start
  FROM {{ source('system_lakeflow', 'job_run_timeline') }}
  WHERE period_start_time >= ({{ audit_today() }} - ({{ w }}) * INTERVAL 1 DAY)
),
final_runs AS (
  SELECT workspace_id, job_id, run_start, result_state, termination_code
  FROM run_rows
  WHERE result_state IS NOT NULL
    AND period_end_time < date_trunc('DAY', {{ audit_now() }})
  QUALIFY ROW_NUMBER() OVER (PARTITION BY workspace_id, job_id, run_id ORDER BY period_end_time DESC) = 1
),
run_fail AS (
  SELECT 'job' AS resource_type, workspace_id, job_id AS resource_id, CAST(run_start AS DATE) AS usage_date,
         COALESCE(NULLIF(termination_code, ''), 'unknown') AS cause
  FROM final_runs
  WHERE result_state IN ('FAILED', 'ERROR', 'TIMED_OUT')
),
fails AS (
  SELECT * FROM stmt_fail
  UNION ALL
  SELECT * FROM run_fail
)
SELECT usage_date,
       resource_type,
       concat(COALESCE(workspace_id, 'account'), ':', resource_id) AS resource_key,
       workspace_id,
       resource_id,
       cause,
       COUNT(*) AS failures
FROM fails
GROUP BY usage_date, resource_type, workspace_id, resource_id, cause
ORDER BY usage_date DESC, resource_type, resource_key, cause
{%- else %}
WITH stmt_fail AS (
  SELECT 'warehouse' AS resource_type, workspace_id, compute.warehouse_id AS resource_id, date(start_time) AS usage_date,
         COALESCE(NULLIF(regexp_extract(error_message, concat('^', chr(92), '[([A-Za-z0-9_.]+)', chr(92), ']'), 1), ''), 'unclassified') AS cause
  FROM {{ source('system_query', 'history') }}
  WHERE execution_status = 'FAILED'
    AND compute.warehouse_id IS NOT NULL
    AND start_time >= {{ audit_today() }} - INTERVAL {{ w }} DAYS
    AND start_time < {{ audit_today() }}
),
run_rows AS (
  SELECT workspace_id, job_id, run_id, period_end_time, result_state, termination_code,
         MIN(period_start_time) OVER (PARTITION BY workspace_id, job_id, run_id) AS run_start
  FROM {{ source('system_lakeflow', 'job_run_timeline') }}
  WHERE period_start_time >= dateadd(day, -{{ w }}, {{ audit_today() }})
),
final_runs AS (
  SELECT workspace_id, job_id, run_start, result_state, termination_code
  FROM run_rows
  WHERE result_state IS NOT NULL
    AND period_end_time < date_trunc('DAY', {{ audit_now() }})
  QUALIFY ROW_NUMBER() OVER (PARTITION BY workspace_id, job_id, run_id ORDER BY period_end_time DESC) = 1
),
run_fail AS (
  SELECT 'job' AS resource_type, workspace_id, job_id AS resource_id, date(run_start) AS usage_date,
         COALESCE(NULLIF(termination_code, ''), 'unknown') AS cause
  FROM final_runs
  WHERE result_state IN ('FAILED', 'ERROR', 'TIMED_OUT')
),
fails AS (
  SELECT * FROM stmt_fail
  UNION ALL
  SELECT * FROM run_fail
)
SELECT usage_date,
       resource_type,
       concat(COALESCE(workspace_id, 'account'), ':', resource_id) AS resource_key,
       workspace_id,
       resource_id,
       cause,
       COUNT(*) AS failures
FROM fails
GROUP BY usage_date, resource_type, workspace_id, resource_id, cause
ORDER BY usage_date DESC, resource_type, resource_key, cause
{%- endif %}
) q
{%- if not loop.last %}
UNION ALL
{%- endif %}
{%- endfor %}
